import {layout,pages,filenames,esc,safeUrl} from './render.mjs';
const $=s=>document.querySelector(s);
let token='',data=null,baseline='',section='home',dirty=false;
const repository='arcyuke/les',branch='main',contentPath='dist/data/content.json';
const pending=new Map();
const tabs={home:'Главная',about:'О нас',services:'Услуги: тексты',programs:'Программы и цены',venuesPage:'Площадки: тексты',venues:'Площадки',reviews:'Отзывы',videos:'Видео',contacts:'Контакты',brand:'Подвал и компания',ui:'Кнопки и меню',booking:'Форма бронирования',privacy:'Конфиденциальность',settings:'Подключение сервера',requests:'Заявки',telegram:'Telegram'};
const labels={name:'Название / имя',descriptor:'Подпись к логотипу',city:'Город',description:'Описание',phone:'Основной телефон',phoneHref:'Ссылка звонка',phone2:'Второй телефон',phone2Href:'Ссылка второго телефона',manager:'Подпись контактов',vk:'Ссылка на ВК',footerText:'Текст подвала',copyright:'Подпись внизу',nav:'Меню',title:'Заголовок',titleAccent:'Вторая строка заголовка',text:'Текст',eyebrow:'Надпись над заголовком',image:'Фотография',imageAlt:'Описание фотографии',imageCaption:'Подпись фотографии',stamp:'Текст круглой отметки',stats:'Числа на главной',value:'Значение',label:'Подпись',introLabel:'Подпись вступления',introTitle:'Заголовок вступления',introText:'Текст вступления',programsLabel:'Подпись раздела программ',programsTitle:'Заголовок программ',venuesLabel:'Подпись площадок',venuesTitle:'Заголовок площадок',ctaLabel:'Подпись приглашения',ctaTitle:'Заголовок приглашения',ctaText:'Текст приглашения',storyTitle:'Заголовок истории',storyText:'История',values:'Преимущества',galleryTitle:'Заголовок галереи',gallery:'Галерея',alt:'Описание изображения',priceNote:'Пояснение к ценам',filters:'Категории фильтров',faqTitle:'Заголовок вопросов',faqs:'Вопросы и ответы',question:'Вопрос',answer:'Ответ',id:'Идентификатор (не менять после запуска)',category:'Категория',tag:'Возраст / подпись',price:'Цена',unit:'За что указана цена',visible:'Показывать',featured:'На главной',district:'Район',address:'Адрес',mapUrl:'Ссылка на карту',equipmentTitle:'Заголовок оснащения',equipment:'Оснащение',equipmentNote:'Пояснение к оснащению',phoneLabel:'Подпись телефона',vkLabel:'Подпись сообщества',vkText:'Текст о сообществе',checklistTitle:'Заголовок списка',checklist:'Список',locationTitle:'Заголовок адресов',items:'Список',empty:'Текст при отсутствии материалов',linkText:'Текст ссылки',url:'Ссылка / URL видео',poster:'Обложка видео',date:'Дата',operator:'Данные оператора персональных данных',ready:'Политика заполнена и готова к запуску',sections:'Разделы',apiBase:'Адрес сервера заявок (HTTPS; пусто — этот же сайт)',repository:'Репозиторий',branch:'Ветка',contentPath:'Файл контента',nameLabel:'Подпись имени',programLabel:'Подпись программы',venueLabel:'Подпись площадки',dateLabel:'Подпись даты',timeLabel:'Подпись времени',peopleLabel:'Подпись количества',commentLabel:'Подпись комментария',consentLabel:'Текст согласия',submitLabel:'Текст отправки',successTitle:'Заголовок успеха',successText:'Текст после отправки',offlineText:'Текст до подключения сервера',errorText:'Ошибка',selectLabel:'Пустой вариант выбора',note:'Пояснение формы'};
const templates={programs:{id:'',title:'Новая программа',category:'1–4 класс',tag:'',description:'',image:'',imageAlt:'',price:'',unit:'',visible:true,featured:false},venues:{id:'',name:'Новая площадка',district:'',address:'',description:'',image:'',imageAlt:'',mapUrl:'',visible:true},'reviews.items':{name:'',date:'',text:'',url:'',visible:true},'videos.items':{title:'',url:'',poster:'',visible:true},'about.gallery':{image:'',alt:''}};
const status=(message,error=false)=>{$('#admin-status').textContent=message;$('#admin-status').style.color=error?'#9a3022':'';};
const get=(path)=>path.reduce((v,k)=>v[k],data);
function set(path,value){const parent=get(path.slice(0,-1));parent[path.at(-1)]=value;dirty=true;}
const b64=text=>{const bytes=new TextEncoder().encode(text);let str='';for(let i=0;i<bytes.length;i+=8192)str+=String.fromCharCode(...bytes.subarray(i,i+8192));return btoa(str);};
const decode=s=>new TextDecoder().decode(Uint8Array.from(atob(s.replace(/\s/g,'')),c=>c.charCodeAt(0)));
async function gh(route,method='GET',body){if(!token)throw Error('Для сохранения нужен GitHub-токен.');const r=await fetch(`https://api.github.com/repos/${repository}/${route}`,{method,headers:{Authorization:`Bearer ${token}`,Accept:'application/vnd.github+json',...(body?{'Content-Type':'application/json'}:{})},body:body?JSON.stringify(body):undefined});if(!r.ok){if(r.status===401)throw Error('Токен недействителен или истёк. Войдите заново.');if(r.status===403)throw Error('Нет доступа на запись либо превышен лимит GitHub.');throw Error(`GitHub: ошибка ${r.status}. Изменения не опубликованы.`);}return r.json();}
$('#login').addEventListener('submit',async e=>{e.preventDefault();token=$('#token').value.trim();$('#token').value='';status('Подключение к репозиторию…');try{const ref=await gh('git/ref/heads/'+branch);baseline=ref.object.sha;const file=await gh(`contents/${contentPath}?ref=${baseline}`);data=JSON.parse(decode(file.content));await openEditor();status('Репозиторий подключён. Изменения появятся после сохранения и публикации хостингом.');}catch(error){token='';status(error.message,true);}});
$('#demo').addEventListener('click',async()=>{try{data=await (await fetch('data/content.json')).json();await openEditor();status('Просмотр редактора. Сохранение в GitHub доступно после входа.');}catch{status('Не удалось загрузить содержание сайта.',true);}});
async function openEditor(){$('#login-panel').hidden=true;$('#workspace').hidden=false;$('#logout').hidden=false;$('#publish').disabled=!token;$('#tabs').replaceChildren();for(const[key,label]of Object.entries(tabs)){const b=document.createElement('button');b.type='button';b.textContent=label;b.dataset.section=key;b.addEventListener('click',()=>{section=key;void render();});$('#tabs').append(b);}await render();}
$('#logout').addEventListener('click',()=>{if(dirty&&!confirm('Выйти без сохранения изменений?'))return;token='';data=null;baseline='';dirty=false;for(const p of pending.values())URL.revokeObjectURL(p.preview);pending.clear();$('#workspace').hidden=true;$('#editor').replaceChildren();$('#preview-frame').srcdoc='';$('#preview-frame').hidden=true;$('#login-panel').hidden=false;$('#logout').hidden=true;status('Вы вышли. Токен удалён из памяти.');});
function field(value,path,parent){const key=String(path.at(-1)),name=labels[key]||data.ui?.nav?.[key]||key;
 if(Array.isArray(value)){const box=document.createElement('fieldset');box.className='admin-fieldset';const legend=document.createElement('legend');legend.textContent=name;box.append(legend);value.forEach((item,i)=>{const group=document.createElement('div');group.className='array-item';field(item,[...path,i],group);const actions=document.createElement('div');actions.className='admin-tools';for(const[label,action]of [['Выше',()=>{if(i>0)[value[i-1],value[i]]=[value[i],value[i-1]];}],['Ниже',()=>{if(i<value.length-1)[value[i+1],value[i]]=[value[i],value[i+1]];}],['Удалить',()=>{value.splice(i,1);}]]){const b=document.createElement('button');b.type='button';b.textContent=label;b.addEventListener('click',()=>{if(label==='Удалить'&&!confirm('Удалить элемент из черновика?'))return;action();dirty=true;void render();});actions.append(b);}group.append(actions);box.append(group);});const add=document.createElement('button');add.type='button';add.className='small-button';add.textContent='Добавить';add.addEventListener('click',()=>{const t=templates[path.join('.')];const item=t?structuredClone(t):value.length?structuredClone(value.at(-1)):'';if(item&&typeof item==='object'&&'id'in item)item.id=crypto.randomUUID();value.push(item);dirty=true;void render();});box.append(add);parent.append(box);return;}
 if(value&&typeof value==='object'){for(const[k,v]of Object.entries(value))field(v,[...path,k],parent);return;}
 const label=document.createElement('label');label.textContent=name;const input=typeof value==='boolean'?document.createElement('input'):String(value).length>95||['text','description','comment','answer','consentLabel'].includes(key)?document.createElement('textarea'):document.createElement('input');input.type=typeof value==='boolean'?'checkbox':'text';if(typeof value==='boolean')input.checked=value;else input.value=value??'';if(input.tagName==='TEXTAREA')input.rows=3;if(['repository','branch','contentPath'].includes(key))input.readOnly=true;input.addEventListener('input',()=>set(path,typeof value==='boolean'?input.checked:input.value));label.append(input);parent.append(label);
 if(['image','poster'].includes(key)){const upload=document.createElement('input');upload.type='file';upload.accept='image/jpeg,image/png,image/webp';upload.setAttribute('aria-label','Загрузить фотографию');upload.addEventListener('change',async()=>{const file=upload.files[0];if(!file)return;if(file.size>8*1024*1024){status('Фото должно быть меньше 8 МБ.',true);return;}const ext={'image/jpeg':'jpg','image/png':'png','image/webp':'webp'}[file.type];if(!ext){status('Используйте JPEG, PNG или WebP.',true);return;}const bytes=new Uint8Array(await file.arrayBuffer());let raw='';for(let i=0;i<bytes.length;i+=8192)raw+=String.fromCharCode(...bytes.subarray(i,i+8192));const target=`assets/uploads/${crypto.randomUUID()}.${ext}`;pending.set(target,{base64:btoa(raw),preview:URL.createObjectURL(file)});set(path,target);await render();});parent.append(upload);if(value){const img=document.createElement('img');img.src=pending.get(value)?.preview||safeUrl(value);img.alt='Предпросмотр фотографии';parent.append(img);}}
}
async function render(){$('#preview-frame').hidden=true;$('#editor').replaceChildren();document.querySelectorAll('[data-section]').forEach(b=>b.classList.toggle('active',b.dataset.section===section));if(section==='requests')return renderBookings();if(section==='telegram')return renderTelegram();const panel=document.createElement('section');panel.className='admin-panel';const title=document.createElement('h2');title.textContent=tabs[section];panel.append(title);if(section==='settings'){const p=document.createElement('p');p.textContent='Сервер нужен для заявок и Telegram. На статическом хостинге без сервера форма показывает контакты для связи.';panel.append(p);}if(section==='privacy'){const p=document.createElement('p');p.className='admin-warning';p.textContent='До запуска заявок заполните данные оператора и окончательный текст политики. Приём заявок также включается на сервере.';panel.append(p);}field(data[section],[section],panel);$('#editor').append(panel);}
$('#preview').addEventListener('click',()=>{let page=section==='programs'?'services':section==='venuesPage'?'venues':pages.includes(section)?section:'home';let html=layout(data,page);html=html.replace('<head>','<head><base href="'+esc(new URL('.',location.href).href)+'">');for(const[url,file]of pending)html=html.replaceAll(url,file.preview);$('#preview-frame').srcdoc=html;$('#preview-frame').hidden=false;$('#preview-frame').scrollIntoView({behavior:'smooth'});});
$('#export').addEventListener('click',()=>{const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='les-content.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);});
$('#publish').addEventListener('click',async()=>{if(!token)return;const button=$('#publish');button.disabled=true;status('Сохранение изменений в GitHub…');try{const ref=await gh('git/ref/heads/'+branch);if(ref.object.sha!==baseline)throw Error('Репозиторий изменился после входа. Скачайте черновик JSON и войдите заново, чтобы не перезаписать чужие изменения.');const commit=await gh('git/commits/'+baseline);const tree=[{path:contentPath,mode:'100644',type:'blob',content:JSON.stringify(data,null,2)+'\n'}];for(const p of pages)tree.push({path:'dist/'+filenames[p],mode:'100644',type:'blob',content:layout(data,p)});for(const[p,file]of pending){const blob=await gh('git/blobs','POST',{content:file.base64,encoding:'base64'});tree.push({path:'dist/'+p,mode:'100644',type:'blob',sha:blob.sha});}const created=await gh('git/trees','POST',{base_tree:commit.tree.sha,tree});const next=await gh('git/commits','POST',{message:'Update LES content from admin',tree:created.sha,parents:[baseline]});await gh('git/refs/heads/'+branch,'PATCH',{sha:next.sha,force:false});baseline=next.sha;dirty=false;for(const file of pending.values())URL.revokeObjectURL(file.preview);pending.clear();status('Сохранено в GitHub. Подключённый хостинг должен опубликовать новую версию сайта.');}catch(e){status(e.message,true);}finally{button.disabled=false;}});
async function api(route,method='GET',body){if(!token)throw Error('Войдите через GitHub, чтобы управлять заявками и Telegram.');const r=await fetch(data.settings.apiBase.replace(/\/$/,'')+'/api/admin/'+route,{method,headers:{Authorization:`Bearer ${token}`,...(body?{'Content-Type':'application/json'}:{})},body:body?JSON.stringify(body):undefined});let j;try{j=await r.json();}catch{throw Error('Сервер заявок ещё не подключён. Его адрес задаётся в разделе «Подключение сервера».');}if(!r.ok)throw Error(j.error||'Не удалось выполнить запрос.');return j;}
async function renderBookings(){const el=$('#editor');el.innerHTML='<section class="admin-panel"><h2>Заявки на бронирование</h2><p>После согласования с клиентом подтвердите заявку. Одна подтверждённая бронь закрывает выбранную площадку на весь день; интервалы можно будет уточнить после согласования расписания.</p><div id="request-list" class="admin-table"></div></section>';try{const result=await api('bookings');const box=$('#request-list');if(!result.bookings.length){box.textContent='Заявок пока нет.';return;}const table=document.createElement('table');table.innerHTML='<thead><tr><th>Дата и площадка</th><th>Контакты</th><th>Программа</th><th>Статус</th></tr></thead>';const body=document.createElement('tbody');for(const b of result.bookings){const tr=document.createElement('tr');tr.innerHTML=`<td>${esc(b.date)} ${esc(b.time)}<br>${esc(b.venueTitle)}<br>№ ${esc(b.id)}</td><td>${esc(b.name)}<br>${esc(b.phone)}</td><td>${esc(b.programTitle)}<br>${esc(b.people)} участников<br>${esc(b.comment)}</td>`;const td=document.createElement('td'),select=document.createElement('select');for(const[v,label]of [['pending','Ожидает'],['confirmed','Подтверждена'],['cancelled','Отменена']]){const option=new Option(label,v);option.selected=b.status===v;select.add(option);}select.addEventListener('change',async()=>{try{await api('bookings','PATCH',{id:b.id,status:select.value});b.status=select.value;status('Статус заявки сохранён.');}catch(e){select.value=b.status;status(e.message,true);}});td.append(select);tr.append(td);body.append(tr);}table.append(body);box.append(table);if(result.notifications){const p=document.createElement('p');p.textContent=`Ожидают доставки в Telegram: ${result.notifications}`;box.append(p);}}catch(e){$('#request-list').textContent=e.message;}}
async function renderTelegram(){const el=$('#editor');el.innerHTML='<section class="admin-panel"><h2>Получатели в Telegram</h2><p>Создайте личную ссылку для администратора. Он откроет её и нажмёт «Старт» у бота. Затем обновите список и включите уведомления для этого человека. Можно подключить нескольких получателей.</p><div id="telegram-content"></div></section>';try{const result=await api('telegram');const box=$('#telegram-content');if(!result.configured){box.textContent='Бот ещё не подключён. На сервере нужно задать TELEGRAM_BOT_TOKEN; в GitHub этот токен не сохраняется.';return;}const tools=document.createElement('div');tools.className='admin-tools';const invite=document.createElement('button');invite.textContent='Создать ссылку приглашения';invite.addEventListener('click',async()=>{try{const r=await api('invite','POST',{});const p=document.createElement('p'),a=document.createElement('a');a.href=r.url;a.target='_blank';a.rel='noopener noreferrer';a.textContent=r.url;p.append(a);box.append(p);status('Ссылка действует 24 часа и предназначена для одного администратора.');}catch(e){status(e.message,true);}});const refresh=document.createElement('button');refresh.textContent='Обновить список';refresh.addEventListener('click',async()=>{try{await api('telegram/sync','POST',{});await renderTelegram();}catch(e){status(e.message,true);}});tools.append(invite,refresh);box.append(tools);for(const r of result.recipients){const row=document.createElement('div');row.className='array-item';const label=document.createElement('label'),check=document.createElement('input');check.type='checkbox';check.checked=r.enabled;label.append(check,document.createTextNode(`${r.name} ${r.username?'(@'+r.username+')':''}`));check.addEventListener('change',async()=>{try{await api('telegram','PATCH',{id:r.id,enabled:check.checked});status('Получатели обновлены.');}catch(e){check.checked=!check.checked;status(e.message,true);}});const remove=document.createElement('button');remove.className='small-button';remove.textContent='Удалить получателя';remove.addEventListener('click',async()=>{if(!confirm('Удалить этого получателя уведомлений?'))return;try{await api('telegram','DELETE',{id:r.id});await renderTelegram();}catch(e){status(e.message,true);}});row.append(label,remove);box.append(row);}}catch(e){$('#telegram-content').textContent=e.message;}}
window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue='';}});
